// Page Reveal Transition using GSAP
// Curtain columns reveal from center outward: 4th → 3rd & 5th → 2nd & 6th → 1st & 7th

import gsap from 'gsap';
import { SplitText } from 'gsap/SplitText';

gsap.registerPlugin(SplitText);

export function initPageTransition() {
    const wrapper = document.querySelector('.page-reveal-transition');
    if (!wrapper) return;

    const columns = wrapper.querySelectorAll('.curtain-column');
    const background = wrapper.querySelector('.page-reveal-background');
    const contentArea = wrapper.querySelector('.content-area');
    const heading = contentArea?.querySelector('h5');
    const loaderProgress = contentArea?.querySelector('.loader-progress');
    const loaderLine = contentArea?.querySelector('.loader-line');
    const loaderPercentage = contentArea?.querySelector('.loader-percentage');

    if (!columns.length) return;

    // Prevent scrolling during transition
    document.body.style.overflow = 'hidden';

    // Split heading into characters with mask wrapper
    let split;
    if (heading) {
        heading.style.opacity = 1;
        split = new SplitText(heading, {
            type: 'chars',
            mask: 'chars'
        });
        // Set initial state: characters pushed down below mask
        gsap.set(split.chars, { yPercent: 110 });
    }

    // Master timeline
    const tl = gsap.timeline({
        onComplete: () => {
            document.body.style.overflow = '';
            wrapper.classList.add('transition-done');
            // Clean up SplitText
            if (split) split.revert();
            // Remove from DOM after transition
            gsap.set(wrapper, { display: 'none' });
        }
    });

    // Phase 1: Reveal characters one by one from below the mask
    if (split) {
        tl.to(split.chars, {
            yPercent: 0,
            duration: 0.3,
            stagger: 0.03,
            ease: 'power3.out'
        }, '-=0.1');
    }

    tl.to([loaderProgress, loaderPercentage], {
        opacity: 1,
        duration: 0.4,
        ease: 'power2.out'
    }, '-=0.2')

    // Phase 2: Animate the loader from 0% to 100%
    .to(loaderLine, {
        scaleX: 1,
        duration: 1.6,
        ease: 'power2.inOut',
        onUpdate: function () {
            if (loaderPercentage) {
                const progress = Math.round(this.progress() * 100);
                loaderPercentage.textContent = progress + '%';
            }
        }
    }, '-=0.1')

    // Phase 3: Fade out content area
    .to(contentArea, {
        opacity: 0,
        y: -20,
        duration: 0.5,
        ease: 'power2.in'
    }, '-=0.2')

    // Phase 4: Reveal curtain columns from center outward
    // Dynamically pick only visible columns (7 on desktop, 3 on mobile)
    const visibleColumns = [...columns].filter(col => col.offsetParent !== null || getComputedStyle(col).display !== 'none');
    const count = visibleColumns.length;
    const center = Math.floor(count / 2);

    // Build center-outward groups: center first, then pairs expanding out
    const groups = [[visibleColumns[center]]];
    for (let i = 1; i <= center; i++) {
        const pair = [];
        if (center - i >= 0) pair.push(visibleColumns[center - i]);
        if (center + i < count) pair.push(visibleColumns[center + i]);
        if (pair.length) groups.push(pair);
    }

    groups.forEach((group, i) => {
        tl.to(group, {
            scaleY: 0,
            transformOrigin: 'top center',
            duration: 0.5,
            ease: 'power3.in',
        }, i === 0 ? '+=0.1' : '-=0.35');
    });

    // Phase 5: Fade out the background
    tl.to(background, {
        y: '-100%',
        duration: 0.5,
    }, '-=0.2');
}
