// Offcanvas Menu - GSAP animated hamburger menu with stagger

import gsap from 'gsap';

let menuOpen = false;
let openTl = null;

export function initOffcanvasMenu() {
    const hamburger = document.querySelector('.humburger_menu');
    const overlay = document.querySelector('.menu-overlay-bg');
    const menu = document.querySelector('.offcanvas-menu-main');
    const bgOverlay = menu?.querySelector('.bg-menu-overlay');
    const closeBtn = menu?.querySelector('.close-menu');

    if (!hamburger || !overlay || !menu || !bgOverlay) return;

    const menuItems = menu.querySelectorAll('.main-menu-items > li');

    // Set initial hidden states
    gsap.set(overlay, { autoAlpha: 0 });
    gsap.set(menu, { width: 0 });
    gsap.set(bgOverlay, { width: '100%' });
    gsap.set(closeBtn, { autoAlpha: 0, rotate: -90 });
    gsap.set(menuItems, { autoAlpha: 0, y: 40 });

    function buildTimeline() {
        const tl = gsap.timeline({ paused: true });

        // 1. Menu panel width expands (bg-overlay covers content)
        tl.to(overlay, {
            autoAlpha: 1,
            duration: 0.4,
            ease: 'power2.out'
        })
        .to(menu, {
            width: '100%',
            duration: 0.6,
            ease: 'power3.inOut'
        },'<')
    
        // 2. bg-overlay shrinks to 0%, revealing menu content behind it
        .to(bgOverlay, {
            width: '0%',
            duration: 0.5,
            ease: 'power3.inOut'
        }, '-=0.1')
        // 3. Close button spins in
        .to(closeBtn, {
            autoAlpha: 1,
            rotate: 0,
            duration: 0.4,
            ease: 'power2.out'
        }, '-=0.3')
        // 4. Stagger menu items
        .to(menuItems, {
            autoAlpha: 1,
            y: 0,
            duration: 0.5,
            stagger: 0.08,
            ease: 'power3.out'
        }, '-=0.2');

        return tl;
    }

    openTl = buildTimeline();

    function openMenu() {
        if (menuOpen) return;
        menuOpen = true;
        document.body.style.overflow = 'hidden';
        openTl.timeScale(1).play();
    }

    function closeMenu() {
        if (!menuOpen) return;
        menuOpen = false;
        document.body.style.overflow = '';
        openTl.timeScale(1.4).reverse();
    }

    hamburger.addEventListener('click', openMenu);
    closeBtn.addEventListener('click', closeMenu);
    overlay.addEventListener('click', closeMenu);

    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && menuOpen) closeMenu();
    });
}
