// Art cards scroll-pin animation with GSAP ScrollTrigger
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const MOBILE_BREAKPOINT = 992; // Bootstrap lg

function initArtCardsScroll() {
    const section = document.querySelector('.section-art-cards');
    const cards = document.querySelectorAll('.section-art-cards .art-card');
    const outer = document.querySelector('.section-art-cards .art-card-outer');

    if (!section || !cards.length || !outer) return;

    let mm = gsap.matchMedia();

    mm.add(`(min-width: ${MOBILE_BREAKPOINT}px)`, () => {
        const cardCount = cards.length;
        const scaleBack = 0.95;
        const getRotation = (i) => (i % 2 === 0 ? -1 : 1); // alternate: left, right

        // Set initial states: all cards stacked, first one active
        gsap.set(cards, {
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            width: '100%',
            transformOrigin: 'top center',
            zIndex: (i) => (i === 0 ? cardCount : cardCount - 1 - i),
            scale: (i) => (i === 0 ? 1 : scaleBack),
            rotation: 0,
            yPercent: (i) => (i === 0 ? 0 : 150)
        });

        // Build timeline for each card transition
        const pinOffset = 120;
        const tl = gsap.timeline({
            scrollTrigger: {
                trigger: outer,
                start: `top ${pinOffset}px`,
                end: () => `+=${cardCount * window.innerHeight}`,
                pin: outer,
                scrub: 1
            }
        });

        // For each card after the first: bring it in, scale previous back
        for (let i = 1; i < cardCount; i++) {
            const prevCard = cards[i - 1];
            const currCard = cards[i];

            tl.set(currCard, { zIndex: 999 }, (i - 1));

            tl.to(prevCard, {
                scale: scaleBack,
                rotation: getRotation(i - 1),
                transformOrigin: 'top center',
                duration: 1
            }, (i - 1));

            tl.fromTo(currCard, {
                yPercent: 150,
                scale: scaleBack,
                rotation: 0,
                transformOrigin: 'top center',
                zIndex: 999
            }, {
                yPercent: 0,
                scale: 1,
                rotation: 0,
                transformOrigin: 'top center',
                zIndex: 999,
                duration: 1
            }, (i - 1));
        }

        return () => {
            // Optional: any cleanup if needed (matchMedia handles most ScrollTrigger cleanup automatically)
        };
    });
}

export { initArtCardsScroll };
