/**
 * Image trail animation for venue section - GSAP only.
 * Adapted from Codrops MotionTrailAnimations demo3: https://github.com/codrops/MotionTrailAnimations
 */

import gsap from 'gsap';

const body = document.body;
const docEl = document.documentElement;

// Utilities (no external deps)
const lerp = (a, b, n) => (1 - n) * a + n * b;
const distance = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
// Returns viewport coordinates (for content-relative positioning when section is in view)
const getPointerPos = (ev) => {
    let posx = 0, posy = 0;
    if (!ev) ev = window.event;
    const e = ev.touches?.[0] || ev;
    if (e.clientX != null || e.clientY != null) {
        posx = e.clientX + body.scrollLeft + docEl.scrollLeft;
        posy = e.clientY + body.scrollTop + docEl.scrollTop;
    }
    return { x: posx, y: posy };
};
const getPointerPosViewport = (ev) => {
    const e = ev?.touches?.[0] || ev;
    return e ? { x: e.clientX, y: e.clientY } : { x: 0, y: 0 };
};
const getMouseDistance = (a, b) => distance(a.x, a.y, b.x, b.y);

// Preload images via native Image (GSAP only - no imagesLoaded)
function preloadTrailImages(selector) {
    return new Promise((resolve) => {
        const el = document.querySelector(selector);
        if (!el) return resolve();
        const inners = el.querySelectorAll('.content__img-inner');
        if (!inners.length) return resolve();
        const promises = [];
        inners.forEach((inner) => {
            const bg = getComputedStyle(inner).backgroundImage;
            const match = bg.match(/url\(['"]?([^'")]+)['"]?\)/);
            if (match) {
                promises.push(new Promise((res) => {
                    const img = new Image();
                    img.onload = res;
                    img.onerror = res;
                    img.src = match[1];
                }));
            }
        });
        Promise.all(promises).then(resolve);
    });
}

class VenueImage {
    constructor(DOM_el) {
        this.DOM = { el: DOM_el, inner: DOM_el.querySelector('.content__img-inner') };
        this.getRect();
        window.addEventListener('resize', () => this.resize());
    }
    resize() {
        gsap.set(this.DOM.el, { scale: 1, x: 0, y: 0, opacity: 0 });
        this.getRect();
    }
    getRect() {
        this.rect = this.DOM.el.getBoundingClientRect();
    }
}

let mousePos = { x: 0, y: 0 };
let mousePosViewport = { x: 0, y: 0 };
let cacheMousePos = { ...mousePos };
let lastMousePos = { ...mousePos };

const handlePointerMove = (ev) => {
    mousePos = ev.touches ? getPointerPos(ev.touches[0]) : getPointerPos(ev);
    mousePosViewport = ev.touches ? getPointerPosViewport(ev.touches[0]) : getPointerPosViewport(ev);
};

window.addEventListener('mousemove', handlePointerMove);
window.addEventListener('touchmove', handlePointerMove);

function isPointerInRect(rect, x, y) {
    return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
}

class ImageTrail {
    constructor(DOM_el, sectionEl) {
        this.DOM = { el: DOM_el };
        this.sectionEl = sectionEl;
        this.images = [...DOM_el.querySelectorAll('.content__img')].map((img) => new VenueImage(img));
        this.imagesTotal = this.images.length;
        this.imgPosition = 0;
        this.zIndexVal = 1;
        this.activeImagesCount = 0;
        this.isIdle = true;
        this.threshold = 80;
        this.contentRect = DOM_el.getBoundingClientRect();

        const onPointerMoveEv = () => {
            cacheMousePos = { ...mousePos };
            requestAnimationFrame(() => this.render());
            window.removeEventListener('mousemove', onPointerMoveEv);
            window.removeEventListener('touchmove', onPointerMoveEv);
        };
        window.addEventListener('mousemove', onPointerMoveEv);
        window.addEventListener('touchmove', onPointerMoveEv);
    }

    render() {
        this.contentRect = this.DOM.el.getBoundingClientRect();
        const sectionRect = this.sectionEl?.getBoundingClientRect();
        const inSection = sectionRect && isPointerInRect(sectionRect, mousePosViewport.x, mousePosViewport.y);

        const dist = getMouseDistance(mousePos, lastMousePos);
        cacheMousePos.x = lerp(cacheMousePos.x ?? mousePos.x, mousePos.x, 0.1);
        cacheMousePos.y = lerp(cacheMousePos.y ?? mousePos.y, mousePos.y, 0.1);

        if (inSection && dist > this.threshold) {
            this.showNextImage();
            lastMousePos = { ...mousePos };
        }

        if (this.isIdle && this.zIndexVal !== 1) {
            this.zIndexVal = 1;
        }

        requestAnimationFrame(() => this.render());
    }

    showNextImage() {
        ++this.zIndexVal;
        this.imgPosition = this.imgPosition < this.imagesTotal - 1 ? this.imgPosition + 1 : 0;
        const img = this.images[this.imgPosition];
        img.getRect();

        const r = this.contentRect;
        const scrollX = window.scrollX ?? docEl.scrollLeft;
        const scrollY = window.scrollY ?? docEl.scrollTop;
        const fromX = (cacheMousePos.x - scrollX) - r.left - img.rect.width / 2;
        const fromY = (cacheMousePos.y - scrollY) - r.top - img.rect.height / 2;
        const toX = mousePosViewport.x - r.left - img.rect.width / 2;
        const toY = mousePosViewport.y - r.top - img.rect.height / 2;

        gsap.killTweensOf(img.DOM.el);

        img.timeline = gsap
            .timeline({
                onStart: () => {
                    this.activeImagesCount++;
                    this.isIdle = false;
                },
                onComplete: () => {
                    this.activeImagesCount--;
                    if (this.activeImagesCount === 0) this.isIdle = true;
                },
            })
            .fromTo(
                img.DOM.el,
                {
                    opacity: 1,
                    scale: 0,
                    zIndex: this.zIndexVal,
                    xPercent: 0,
                    yPercent: 0,
                    x: fromX,
                    y: fromY,
                },
                {
                    duration: 0.4,
                    ease: 'power1',
                    scale: 1,
                    x: toX,
                    y: toY,
                },
                0
            )
            .fromTo(
                img.DOM.inner,
                { scale: 1.2 },
                { duration: 0.4, ease: 'power1', scale: 1 },
                0
            )
            .to(
                img.DOM.el,
                {
                    duration: 0.6,
                    ease: 'power2',
                    opacity: 0,
                    scale: 0.2,
                    xPercent: () => gsap.utils.random(-30, 30),
                    yPercent: 0,
                },
                1
            );
    }
}

export function initVenueTrail() {
    const section = document.querySelector('.section-h-venue');
    const content = section?.querySelector('.venue-trail-content');
    if (!content || !section) return;

    preloadTrailImages('.venue-trail-content').then(() => {
        new ImageTrail(content, section);
    });
}
