// Infinite slider - scroll-driven with eased movement
function initInfiniteSlider() {
    const track = document.querySelector('.infinite-slider__track');
    if (!track) return;

    const items = track.querySelectorAll('.infinite-slider__item');
    const itemCount = items.length;
    if (itemCount < 2) return;

    const gap = 10;
    const scrollFactor = 0.5;
    const ease = 0.1;

    let currentPosition = 0;
    let scrollVelocity = 0;
    let lastScrollY = window.scrollY;
    let lastScrollTime = performance.now();
    let currentScale = 1;

    const minScale = 0.97;
    const velocityToMinScale = 800; // px/s velocity for scale to reach 0.9
    const scaleEase = 0.1;

    window.addEventListener('scroll', () => {
        const now = performance.now();
        const deltaY = window.scrollY - lastScrollY;
        const deltaTime = (now - lastScrollTime) / 1000;
        lastScrollY = window.scrollY;
        lastScrollTime = now;
        if (deltaTime > 0) {
            scrollVelocity = deltaY / deltaTime;
        }
    }, { passive: true });

    function getSetWidth() {
        const half = itemCount / 2;
        let w = 0;
        for (let i = 0; i < half; i++) {
            w += items[i].offsetWidth + gap;
        }
        return w > 0 ? w : track.scrollWidth / 2;
    }

    function getTargetPosition() {
        const setWidth = getSetWidth();
        if (setWidth <= 0) return 0;
        const scrollY = Math.max(0, window.scrollY);
        return (scrollY * scrollFactor) % setWidth;
    }

    function animate() {
        const setWidth = getSetWidth();
        if (setWidth > 0) {
            scrollVelocity *= 0.92;

            const velocityMagnitude = Math.abs(scrollVelocity);
            const targetScale = Math.max(minScale, Math.min(1, 1 - (velocityMagnitude / velocityToMinScale) * (1 - minScale)));
            currentScale += (targetScale - currentScale) * scaleEase;
            currentScale = Math.max(minScale, Math.min(1, currentScale));

            const target = getTargetPosition();
            let diff = target - currentPosition;
            if (Math.abs(diff) > setWidth / 2) {
                diff += diff > 0 ? -setWidth : setWidth;
            }
            if (Math.abs(diff) > 0.5) {
                currentPosition += diff * ease;
            } else {
                currentPosition = target;
            }
            const position = ((currentPosition % setWidth) + setWidth) % setWidth;
            track.style.transform = `translate3d(-${position}px, 0, 0)`;
            track.style.setProperty('--slider-scale', currentScale);
        }
        requestAnimationFrame(animate);
    }

    const resizeObserver = new ResizeObserver(() => {
        const setWidth = getSetWidth();
        if (setWidth > 0) currentPosition = currentPosition % setWidth;
    });
    resizeObserver.observe(track);

    animate();
}

// Navbar scroll effect (safe to call multiple times - uses single listener)
let navbarScrollInitialized = false;
function initNavbarScrollEffect() {
    if (navbarScrollInitialized) return;
    const navbar = document.querySelector('.main-navigation');
    if (!navbar) return;
    navbarScrollInitialized = true;
    const handleScroll = () => {
        if (window.scrollY > 50) {
            navbar.classList.add('scrolled');
        } else {
            navbar.classList.remove('scrolled');
        }
    };
    window.addEventListener('scroll', handleScroll);
    handleScroll();
}

gsap.registerPlugin(SplitText);

// Team modal popover (GSAP) - same behavior as reference PHP implementation
let teamModalInitialized = false;
function initTeamModalPopover() {
    if (teamModalInitialized) return;
    const modalEl = document.getElementById('team-modal');
    if (!modalEl) return;

    teamModalInitialized = true;

    const pictureEl = modalEl.querySelector('#tm-picture');
    const nameEl = modalEl.querySelector('#tm-name');
    const contentEl = modalEl.querySelector('#tm-content');
    const closeEl = modalEl.querySelector('.tm-close');
    const innerEl = modalEl.querySelector('.tm-inner');

    if (!pictureEl || !nameEl || !contentEl || !closeEl || !innerEl) return;

    const tl = gsap.timeline({ paused: true });
    tl.to(modalEl, {
        duration: 0.3,
        opacity: 1,
        display: 'block'
    })
        .to(modalEl.querySelector('.large-circle'), { duration: 0.8, ease: 'power2.out', opacity: 0, scale: 3 }, '-=0.3')
        .from(pictureEl, { duration: 0.3, ease: 'power2.out', x: 100, opacity: 0, scale: 1 }, '-=0.4')
        .from(nameEl, { duration: 0.3, ease: 'power2.out', x: 40, opacity: 0, scale: 1 }, '-=0.2')
        .from(contentEl, { duration: 0.3, ease: 'power2.out', x: 40, opacity: 0, scale: 1 }, '-=0.2');

    const openModalFor = (teamEl) => {
        const name = teamEl.dataset.teamName || teamEl.querySelector('h5, h6, h2')?.textContent?.trim() || '';
        const role = teamEl.dataset.teamRole || teamEl.querySelector('.card-text.text-primary')?.textContent?.trim() || '';
        const imgUrl = teamEl.querySelector('.img-team')?.getAttribute('src') || teamEl.querySelector('img')?.getAttribute('src') || '';
        const detailsHtml = teamEl.querySelector('.team-details')?.innerHTML || '';

        nameEl.textContent = name;
        pictureEl.setAttribute('src', imgUrl);
        pictureEl.setAttribute('alt', name);

        // Ensure designation is included even if detailsHtml doesn't contain it
        const designationHtml = role ? `<p class="text-primary team-designation">${role}</p>` : '';
        contentEl.innerHTML = detailsHtml || `${designationHtml}<p>Biography coming soon.</p>`;

        document.body.classList.add('team-modal-open');
        modalEl.setAttribute('aria-hidden', 'false');
        tl.play(0);
    };

    document.querySelectorAll('.team-area').forEach((teamEl) => {
        teamEl.addEventListener('click', (e) => {
            // Ignore clicks on gallery fancybox or other links inside
            const target = e.target;
            if (target instanceof Element) {
                const inGallery = target.closest('[data-fancybox]');
                if (inGallery) return;
            }
            e.preventDefault();
            openModalFor(teamEl);
        });
    });

    const closeModal = () => {
        modalEl.setAttribute('aria-hidden', 'true');
        tl.reverse();
        tl.eventCallback('onReverseComplete', () => {
            document.body.classList.remove('team-modal-open');
        });
    };

    closeEl.addEventListener('click', (e) => {
        e.preventDefault();
        closeModal();
    });

    // Close when clicking backdrop (but not inner content)
    modalEl.addEventListener('click', (e) => {
        if (e.target === modalEl) closeModal();
    });

    // Close on ESC
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && modalEl.getAttribute('aria-hidden') === 'false') closeModal();
    });
}

// SplitText heading animation on scroll for .title-head (e.g. "Highest standards of excellence")
function initSplitTextHeadings() {
    const headings = document.querySelectorAll('.title-head');
    if (!headings.length) return;

    const observer = new IntersectionObserver((entries, obs) => {
        entries.forEach((entry) => {
            if (!entry.isIntersecting) return;
            const el = entry.target;
            if (el.dataset.splitAnimated === '1') {
                obs.unobserve(el);
                return;
            }
            el.dataset.splitAnimated = '1';

            // Prepare SplitText animation
            const split = new SplitText(el, {
                type: 'chars',
                mask: 'chars'
            });

            gsap.set(split.chars, { yPercent: 110, opacity: 0 });
            el.style.opacity = 1;

            gsap.to(split.chars, {
                yPercent: 0,
                opacity: 1,
                duration: 0.45,
                stagger: 0.035,
                ease: 'power3.out',
                onComplete: () => {
                    split.revert();
                }
            });

            obs.unobserve(el);
        });
    }, {
        threshold: 0.4
    });

    headings.forEach((heading) => {
        // Hide initially; will be revealed when animated
        if (!heading.style.opacity) {
            heading.style.opacity = '0';
        }
        observer.observe(heading);
    });
}

function initIsotopeGallery() {
    const grids = document.querySelectorAll('.isotope-grid');
    if (grids.length === 0 || typeof window.Isotope === 'undefined') return;

    grids.forEach(grid => {
        const iso = new window.Isotope(grid, {
            itemSelector: '.isotope-item',
            layoutMode: 'masonry',
            percentPosition: true,
            masonry: { columnWidth: '.isotope-item' }
        });

        // Re-layout after all images load
        const imgs = grid.querySelectorAll('img');
        let loaded = 0;
        if (imgs.length === 0) {
            iso.layout();
        } else {
            imgs.forEach(img => {
                const handleImageLoad = () => {
                    loaded++;
                    if (loaded === imgs.length) iso.layout();
                };

                if (img.complete) {
                    handleImageLoad();
                } else {
                    img.addEventListener('load', handleImageLoad);
                }
            });
        }
    });
}



function initIntlTelInput() {
    const phoneInputs = document.querySelectorAll("#mobileNumber");
    if (phoneInputs.length > 0 && typeof window.intlTelInput === 'function') {
        phoneInputs.forEach(input => {
            window.intlTelInput(input, {
                initialCountry: "us",
                separateDialCode: true,
                utilsScript: "https://cdn.jsdelivr.net/npm/intl-tel-input@25.3.0/build/js/utils.js",
            });
        });
    }
}

function initDatePickers() {
    const dateInputs = document.querySelectorAll('#visitDate');
    if (dateInputs.length > 0 && typeof flatpickr === 'function') {
        flatpickr(dateInputs, {
            dateFormat: "m/d/Y",
            minDate: "today",
            disableMobile: "true"
        });
    }
}

function initVideoModal() {
    const videoModal = document.getElementById('videoModal');
    if (!videoModal) return;

    const tourVideo = document.getElementById('tourVideo');
    if (!tourVideo) return;

    const originalSrc = tourVideo.src;

    videoModal.addEventListener('hidden.bs.modal', function () {
        // Reset src to stop the video
        tourVideo.src = "";
        tourVideo.src = originalSrc;
    });
}

function initPageComponents() {
    initPageTransition();
    initNavbarScrollEffect();
    initInfiniteSlider();
    initArtCardsScroll();
    initVenueTrail();
    initTeamModalPopover();
    initSplitTextHeadings();
    initOffcanvasMenu();
    initDatePickers();
    initIntlTelInput();
    initFancybox();
    initIsotopeGallery();
    initVideoModal();
    if (typeof initMultiboxMenu === 'function') initMultiboxMenu();
}

// Initialize everything when DOM is ready
document.addEventListener('DOMContentLoaded', function () {
    initPageComponents();
});

// Export bootstrap and init functions for use in other modules if needed
export { bootstrap, initNavbarScrollEffect };
